-- 월 초과근무: 마지막 달(10월) 근무 기록 합계
UPDATE org.employee_status s SET monthly_overtime_hour = x.h
  FROM (SELECT employee_no, round(SUM(overtime_hour)::numeric, 2)::double precision AS h
          FROM org.employee_record WHERE work_date >= date '2026-10-01' GROUP BY employee_no) x
 WHERE s.employee_no = x.employee_no AND x.h > 0;

COMMIT;
